import type { OperationManifest } from './manifest.js'
import {
  distinct,
  GeneratedNames,
  type NameClaimant,
  type OperationGroup,
  operationClaimant,
  operationGroups,
} from './names.js'

/**
 * Settings for the Go source that {@link renderGoOperations} returns.
 *
 * @public
 */
export interface GoRenderOptions {
  /**
   * The package clause of the generated file, which defaults to `operations`.
   */
  packageName?: string
}

const DEFAULT_GO_PACKAGE = 'operations'

const GO_PACKAGE_NAME = /^[a-z][a-z0-9_]*$/

const GO_CLIENT_IMPORT = 'github.com/assetcorp/sirannon-db/packages/go'

const GO_TAG_PUNCTUATION = '!#$%&()*+-./:;<=>?@[]^_{|}~ '

const OPEN_ROW = 'sirannon.Row'

const OPEN_ARGS = 'map[string]any'

const GO_INITIALISMS = new Set([
  'ACL',
  'API',
  'ASCII',
  'CPU',
  'CSS',
  'DNS',
  'EOF',
  'GUID',
  'HTML',
  'HTTP',
  'HTTPS',
  'ID',
  'IP',
  'JSON',
  'LHS',
  'QPS',
  'RAM',
  'RHS',
  'RPC',
  'SLA',
  'SMTP',
  'SQL',
  'SSH',
  'TCP',
  'TLS',
  'TTL',
  'UDP',
  'UI',
  'UID',
  'UUID',
  'URI',
  'URL',
  'UTF8',
  'VM',
  'XML',
  'XMPP',
  'XSRF',
  'XSS',
])

interface GoReference {
  name: string
  value: string
}

/**
 * Returns Go source that declares a typed `ReadRef` or `WriteRef` variable for every operation in a manifest.
 *
 * The name of each variable is the database identifier followed by the operation name in PascalCase, such as
 * `ItemsItemById` for the `itemById` read of the `items` database. The names of the shared operations start with
 * `Shared`. The function writes arguments and derived columns as struct fields with JSON tags. When an argument
 * has a name that a JSON tag cannot hold, the function types the arguments as `map[string]any`, and when a column
 * has such a name, it types the rows as `sirannon.Row`. The returned source matches what `gofmt` writes.
 *
 * @param manifest - The operations to render.
 * @param options - The package clause of the generated file.
 * @returns The Go source to write.
 * @throws An `Error` when the package name is not a lowercase Go identifier, or when two operations generate the
 * same identifier.
 *
 * @public
 */
export function renderGoOperations(manifest: OperationManifest, options?: GoRenderOptions): string {
  const packageName = options?.packageName ?? DEFAULT_GO_PACKAGE
  if (!GO_PACKAGE_NAME.test(packageName)) {
    throw new Error(`The Go package name '${packageName}' must be a lowercase Go identifier`)
  }
  const names = new GeneratedNames()
  names.claim('RegistryDigest', { owner: 'digest', label: 'the registry digest' })
  const types: string[] = []
  const references: GoReference[] = []

  for (const group of operationGroups(manifest)) {
    references.push(...renderKind(group, 'reads', names, types), ...renderKind(group, 'writes', names, types))
  }

  const lines = [
    '// Code generated by sirannon-codegen. DO NOT EDIT.',
    '',
    `package ${packageName}`,
    '',
    `import sirannon ${JSON.stringify(GO_CLIENT_IMPORT)}`,
    '',
    `const RegistryDigest = ${JSON.stringify(manifest.digest ?? '')}`,
    ...types,
  ]
  if (references.length > 0) {
    const width = Math.max(...references.map(reference => reference.name.length))
    lines.push('', 'var (')
    for (const reference of references) lines.push(`\t${reference.name.padEnd(width)} = ${reference.value}`)
    lines.push(')')
  }
  return `${lines.join('\n')}\n`
}

function renderKind(
  group: OperationGroup,
  kind: 'reads' | 'writes',
  names: GeneratedNames,
  types: string[],
): GoReference[] {
  const references: GoReference[] = []
  for (const [name, shape] of Object.entries(group.operations[kind])) {
    const claimant = operationClaimant(group, kind, name)
    const stem = goName(`${groupStem(group)}${goPascal(name) || 'Operation'}`)
    const args = structType(`${stem}Args`, shape.args, 'sirannon.NoArgs', OPEN_ARGS, claimant, names, types)
    const literal = JSON.stringify(name)
    if (kind === 'writes') {
      references.push({ name: names.claim(stem, claimant), value: `sirannon.WriteRef[${args}]{Name: ${literal}}` })
      continue
    }
    const row =
      shape.columns === null
        ? OPEN_ROW
        : structType(`${stem}Row`, shape.columns, OPEN_ROW, OPEN_ROW, claimant, names, types)
    references.push({ name: names.claim(stem, claimant), value: `sirannon.ReadRef[${args}, ${row}]{Name: ${literal}}` })
  }
  return references
}

function structType(
  typeName: string,
  keys: readonly string[],
  whenEmpty: string,
  whenUntaggable: string,
  claimant: NameClaimant,
  names: GeneratedNames,
  types: string[],
): string {
  const listed = distinct(keys)
  if (listed.length === 0) return whenEmpty
  if (!listed.every(taggable)) return whenUntaggable
  const declared = names.claim(typeName, claimant)
  const fields = new Map<string, string>()
  for (const key of listed) {
    const base = goName(goPascal(key) || 'Field')
    let field = base
    for (let suffix = 2; fields.has(field); suffix++) field = `${base}${suffix}`
    fields.set(field, key)
  }
  const width = Math.max(...[...fields.keys()].map(field => field.length))
  types.push('', `type ${declared} struct {`)
  for (const [field, key] of fields) types.push(`\t${field.padEnd(width)} any \`json:"${key}"\``)
  types.push('}')
  return declared
}

function taggable(key: string): boolean {
  if (key === '' || key === '-') return false
  for (const character of key) {
    if (/[A-Za-z0-9]/.test(character)) continue
    if (!GO_TAG_PUNCTUATION.includes(character)) return false
  }
  return true
}

function goName(value: string): string {
  return /^[A-Z]/.test(value) ? value : `X${value}`
}

function goPascal(value: string): string {
  return value
    .split(/[^A-Za-z0-9]+/)
    .flatMap(part => part.split(/(?<=[a-z0-9])(?=[A-Z])/))
    .filter(word => word.length > 0)
    .map(word => {
      const upper = word.toUpperCase()
      return GO_INITIALISMS.has(upper) ? upper : word[0].toUpperCase() + word.slice(1)
    })
    .join('')
}

function groupStem(group: OperationGroup): string {
  return group.shared ? group.stem : goPascal(group.claimant.label) || 'Database'
}
